 "content": "def transform(grid):
    """Insert 2 between matching non-background cells separated by one cell."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    background = grid[0][0]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c] == background and row[c - 1] != background and row[c + 1] == row[c - 1]:
                out[r][c] = 2
    return out
